update public.taksh_content_assets set title='Marketing Strategy and Funnel: Core Concepts',slug='digital-marketing-fundamentals-marketing-strategy-and-funnel-core-concepts',difficulty='Foundation',status='published',content='{"identity":{"course":"Digital Marketing Fundamentals","module":"Module 1 · Marketing Strategy and Funnel","topic":"Understand","subtopic":"Marketing Strategy and Funnel: Core Concepts","title":"Marketing Strategy and Funnel: Core Concepts","slug":"digital-marketing-fundamentals-marketing-strategy-and-funnel-core-concepts","target_audience":"College students, fresh graduates and entry-level job seekers","difficulty":"Foundation","explanation_depth":"Concept, platform workflow and guided lab","exam_context":"Digital Marketing Fundamentals module assessment and entry-level interview preparation"},"learning_design":{"learning_objectives":[{"objective_id":"understand","objective":"Explain marketing strategy and funnel: core concepts with confidence.","skill_level":"understand"},{"objective_id":"apply","objective":"Practise this workflow: Set the business goal, research the audience, state the offer, map funnel stages and choose metrics before channels.","skill_level":"apply"}],"prerequisites":[],"estimated_learning_minutes":22},"core_content":{"introduction":"Build practical capability in marketing strategy and funnel: core concepts through platform concepts, a guided workflow and a hands-on task.","canonical_definition":"Digital marketing connects a defined audience and value proposition to measurable acquisition, conversion and retention outcomes.","why_it_matters":"Marketing Strategy and Funnel is used in entry-level work and is assessed through practical scenarios and interviews.","concept_explanation":"Principle: Digital marketing connects a defined audience and value proposition to measurable acquisition, conversion and retention outcomes. Example: A training programme targets final-year students with different messages for discovery, evaluat